import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './Login';
import Dashboard from './Dashboard';
import DataDiscovery from './DataDiscovery';
import Compliance from './Compliance';
import BreachAlert from './BreachAlert';
import FileUpload from './FileUpload';
import FileSharing from './FileSharing';
import AuditLogs from './AuditLogs';
import AdvancedDiscovery from './AdvancedDiscovery';
import FileExchange from './FileExchange';

function App() {
  const [activePage, setActivePage] = useState('dashboard');
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const savedUser = localStorage.getItem('user');

    if (token && savedUser) {
      try {
        setUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }
    setLoading(false);
  }, []);

  const handleLoginSuccess = (userData) => {
    setUser(userData);
    setActivePage('dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  if (loading) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        background: 'linear-gradient(135deg, #0a0e27 0%, #1a0033 100%)',
        color: '#e2e8f0'
      }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2.25rem', marginBottom: '1rem' }}>📊</div>
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: '🏠' },
    { id: 'discovery', label: 'Data Discovery', icon: '📊' },
    { id: 'advancedDiscovery', label: 'Advanced Discovery', icon: '🗄️' },
    { id: 'compliance', label: 'Compliance', icon: '✅' },
    { id: 'breach', label: 'Breach Alert', icon: '🚨' },
    { id: 'upload', label: 'File Upload', icon: '📁' },
    { id: 'sharing', label: 'File Sharing', icon: '📥' },
    { id: 'exchange', label: 'File Exchange', icon: '🔄' },
    { id: 'audit', label: 'Audit Logs', icon: '📋' }
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#0a0e27' }}>
      {/* SIDEBAR */}
      <div style={{
        width: '260px',
        background: '#1a1f3a',
        borderRight: '1px solid #10b981',
        display: 'flex',
        flexDirection: 'column',
        color: '#e2e8f0',
        position: 'fixed',
        height: '100vh',
        overflowY: 'auto'
      }}>
        {/* Logo Section */}
        <div style={{
          padding: '1.5rem',
          borderBottom: '1px solid #10b981',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '1.75rem',
            marginBottom: '0.5rem',
            color: '#10b981'
          }}>
            📊 DPDP
          </div>
          <p style={{
            fontSize: '0.875rem',
            color: '#94a3b8',
            margin: '0'
          }}>
            Governance Platform
          </p>
        </div>

        {/* Navigation Menu */}
        <nav style={{ flex: 1, padding: '1rem 0' }}>
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActivePage(item.id)}
              style={{
                width: '100%',
                padding: '0.75rem 1rem',
                background: activePage === item.id ? '#10b981' : 'transparent',
                border: 'none',
                color: activePage === item.id ? '#0a0e27' : '#cbd5e1',
                textAlign: 'left',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                fontSize: '0.95rem',
                fontWeight: activePage === item.id ? '600' : '400',
                transition: 'all 0.3s ease',
                borderLeft: activePage === item.id ? '3px solid #06b6d4' : '3px solid transparent'
              }}
              onMouseEnter={(e) => {
                if (activePage !== item.id) {
                  e.target.style.background = 'rgba(16, 185, 129, 0.1)';
                }
              }}
              onMouseLeave={(e) => {
                if (activePage !== item.id) {
                  e.target.style.background = 'transparent';
                }
              }}
            >
              <span style={{ fontSize: '1.25rem' }}>{item.icon}</span>
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        {/* User Section */}
        <div style={{
          padding: '1rem',
          borderTop: '1px solid #10b981',
          background: 'rgba(16, 185, 129, 0.05)'
        }}>
          <div style={{ marginBottom: '1rem' }}>
            <p style={{ margin: '0 0 0.25rem 0', fontWeight: '600', color: '#10b981' }}>
              {user.username}
            </p>
            <p style={{ margin: '0', fontSize: '0.875rem', color: '#94a3b8' }}>
              {user.department}
            </p>
          </div>
          <button
            onClick={handleLogout}
            style={{
              width: '100%',
              padding: '0.5rem',
              background: '#ef4444',
              border: 'none',
              color: 'white',
              borderRadius: '0.5rem',
              cursor: 'pointer',
              fontSize: '0.9rem',
              fontWeight: '600',
              transition: 'all 0.3s ease'
            }}
            onMouseEnter={(e) => e.target.style.background = '#dc2626'}
            onMouseLeave={(e) => e.target.style.background = '#ef4444'}
          >
            🚪 Logout
          </button>
        </div>
      </div>

      {/* MAIN CONTENT */}
      <div style={{
        marginLeft: '260px',
        flex: 1,
        overflow: 'auto'
      }}>
        {/* TOP BAR */}
        <div style={{
          background: 'linear-gradient(135deg, #1a1f3a 0%, #2d1b4e 100%)',
          padding: '2rem',
          borderBottom: '1px solid #10b981',
          color: 'white',
          position: 'sticky',
          top: 0,
          zIndex: 10
        }}>
          <h1 style={{
            margin: 0,
            fontSize: '2rem',
            fontWeight: '700',
            color: '#10b981'
          }}>
            {navItems.find(item => item.id === activePage)?.label}
          </h1>
        </div>

        {/* PAGE CONTENT */}
        <div style={{
          padding: '2rem',
          minHeight: 'calc(100vh - 120px)'
        }}>
          {activePage === 'dashboard' && <Dashboard user={user} />}
          {activePage === 'discovery' && <DataDiscovery />}
          {activePage === 'advancedDiscovery' && <AdvancedDiscovery />}
          {activePage === 'compliance' && <Compliance />}
          {activePage === 'breach' && <BreachAlert />}
          {activePage === 'upload' && <FileUpload />}
          {activePage === 'sharing' && <FileSharing />}
          {activePage === 'exchange' && <FileExchange />}
          {activePage === 'audit' && <AuditLogs />}
        </div>
      </div>
    </div>
  );
}

export default App;
